import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.ClientCacheStatus{Enabled: true}
ENABLED = bytes.fromhex("01")

# generated by gophertunnel b8bd735:
# &packet.ClientCacheStatus{Enabled: false}
DISABLED = bytes.fromhex("00")

GOLDENS = [
    pytest.param(v2225.ClientCacheStatusPacket(enabled=True), ENABLED, id="enabled"),
    pytest.param(v2225.ClientCacheStatusPacket(enabled=False), DISABLED, id="disabled"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_status_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_status_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_an_empty_body_is_not_a_client_cache_status():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ClientCacheStatusPacket.from_bytes(b"")
